def solve(I,diag=False):
    H,W=len(I),len(I[0])
    blkcells={(r,c) for r in range(H) for c in range(W) if I[r][c]==2}
    markers=[(r,c) for r in range(H) for c in range(W) if I[r][c] not in (0,2)]
    P=set()
    def emit(r,c):
        for s in (-1,1):
            rr=r+s
            while 0<=rr<H: P.add((rr,c)); rr+=s
            cc=c+s
            while 0<=cc<W: P.add((r,cc)); cc+=s
        if diag:
            for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                rr,cc=r+dr,c+dc
                while 0<=rr<H and 0<=cc<W: P.add((rr,cc)); rr+=dr; cc+=dc
    for m in markers: emit(*m)
    return P - set(markers)
